ns16:scriptTask.ns16:script:
tw.local.sqlStatement = new tw.object.listOf.SQLStatement();

for(var i =0 ; i<tw.local.transactions.listLength ; i++){
		tw.local.sqlStatement[i] = new tw.object.SQLStatement();
		tw.local.sqlStatement[i].sql = "SELECT REFERENCENO, POSTINGDATE, AMOUNTLINKEDINBPM FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST( POSTINGDATE AS DATE) = CAST ( ? AS DATE) ";
		tw.local.sqlStatement[i].parameters = new tw.object.listOf.SQLParameter();
		tw.local.sqlStatement[i].parameters[0] = new tw.object.SQLParameter();
		tw.local.sqlStatement[i].parameters[0].value = tw.local.transactions[i].referenceNumber;
		tw.local.sqlStatement[i].parameters[1] = new tw.object.SQLParameter();
		tw.local.sqlStatement[i].parameters[1].value = tw.local.transactions[i].postingDate;
}

if (!!tw.local.results) {
	for (var i = 0; i < tw.local.results.listLength; i++) {
    	  if (tw.local.results[i]["REFERENCENO"] == tw.local.transactions[i].referenceNumber 
     		 && tw.local.results[i]["POSTINGDATE"].getDay() == tw.local.transactions[i].postingDate.getDay()
       	&& tw.local.results[i]["POSTINGDATE"].getMonth() == tw.local.transactions[i].postingDate.getMonth()
        	&& tw.local.results[i]["POSTINGDATE"].getFullYear() == tw.local.transactions[i].postingDate.getFullYear()
          ){
      																 
			tw.local.transactions[i].existAmount = tw.local.results[i]["AMOUNTLINKEDINBPM"] || 0;
		}
}
}
